        case .jev, .laya:   // the Nexus mark (the org brand kit's nexus-mark-ink / nexus-mark-white): ink in light, white in dark
            return Self.nexus
        case .mistral:
            return Self.mistralArt
        case .gemini, .apple:   // gemini draws its own gradient image (ProviderMarkView.swift); apple has no asset yet (a finding, Marks/SOURCES.md)
            return nil
        }
    }

    /// The logo asset the row's probe serves (`rows mac-settings-ai.provider.<id>` field `logo`): the file stem in Marks/.
    var asset: String {
        switch self {
        case .anthropic: "anthropic"
        case .openai, .chatgpt: "openai"
        case .gemini: "gemini"
        case .openrouter: "openrouter"
        case .jev, .laya: "nexus-mark"
        case .mistral: "mistral"
        case .apple: "apple-intelligence"
        }
    }

    /// False when the vendor's real asset is not in the tree: the row then draws nothing (never a stand-in) and the probe says so.
    var present: Bool { self != .apple }

    /// Every mark with its asset, for `rows mac-settings-ai.logos`.
    static var probeRows: [[String: Any]] {
        allCases.map { ["slug": $0.rawValue, "logo": $0.asset, "present": $0.present, "path": "Sources/Features/SettingsWindow/Marks/\($0.asset).svg"] }
    }

    private static let nexus = MarkArt(viewBox: CGSize(width: 242, height: 280), paths: [
        MarkPath(d: "M0 69.855L0.000167052 209.566L120.954 279.421L120.954 176.948C120.954 153.905 108.665 132.613 88.7154 121.092L0 69.855Z", fill: nexusInk, evenOdd: false),
        MarkPath(d: "M164.313 77.4323C184.262 88.9537 196.551 110.246 196.551 133.289L196.551 183.37L241.909 209.566L241.909 107.093C241.909 84.0505 229.62 62.758 209.67 51.2365L120.955 9.45148e-06L120.955 52.3915L164.313 77.4323Z", fill: nexusInk, evenOdd: false),
