        MarkPath(d: "M43.3578 147.287C63.307 158.809 75.5963 180.101 75.5963 203.144L75.5964 253.225L120.954 279.421L120.954 176.948C120.954 153.905 108.665 132.613 88.7154 121.092L0 69.855L7.91518e-05 122.247L43.3578 147.287Z", fill: nexusInk, evenOdd: false),
    ])
    private static let nexusInk = ThemeColor(light: RGBA(hex: 0x0E1116), dark: RGBA(hex: 0xFFFFFF)) // brand-mark: nexus

    /// Mistral's M as mistral.ai serves it (Marks/mistral.svg): ten squares in five fixed colours, drawn as one path per colour.
    private static let mistralArt = MarkArt(viewBox: CGSize(width: 183, height: 183), paths: [
        MarkPath(d: "M33 33h24v23h-24ZM127 33h24v23h-24Z", fill: ThemeColor(light: RGBA(hex: 0xFFAF01), dark: RGBA(hex: 0xFFAF01)), evenOdd: false), // brand-mark: mistral
        MarkPath(d: "M33 56h47v24h-47ZM104 56h47v24h-47Z", fill: ThemeColor(light: RGBA(hex: 0xFF8204), dark: RGBA(hex: 0xFF8204)), evenOdd: false), // brand-mark: mistral
        MarkPath(d: "M33 80h118v23h-118Z", fill: ThemeColor(light: RGBA(hex: 0xFA500F), dark: RGBA(hex: 0xFA500F)), evenOdd: false), // brand-mark: mistral
        MarkPath(d: "M127 103h24v24h-24ZM80 103h24v24h-24ZM33 103h24v24h-24Z", fill: ThemeColor(light: RGBA(hex: 0xE10500), dark: RGBA(hex: 0xE10500)), evenOdd: false), // brand-mark: mistral
        MarkPath(d: "M104 127h70v23h-70ZM10 127h70v23h-70Z", fill: ThemeColor(light: RGBA(hex: 0xC4001D), dark: RGBA(hex: 0xC4001D)), evenOdd: false), // brand-mark: mistral
    ])
}

/// One filled path of a mark, in the mark's own viewBox.
struct MarkPath {
    let d: String
    let fill: ThemeColor
    let evenOdd: Bool
}

/// A vendor mark as vector data: its viewBox and one or more filled paths.
struct MarkArt {
    let viewBox: CGSize
    let paths: [MarkPath]
}
